//! CMAQ-008 v0.1: small, reproducible probe of the real CfC world-model API.
//!
//! This is a diagnostic adapter smoke test, not a SOTA comparison. It evaluates
//! next-state prediction under a source law and an action-effect reversal, against
//! persistence and zero-prediction baselines. The evaluator owns the transition law;
//! predictions are generated by HierarchicalCfCWorldModel::predict.

use std::process;
use symthaea::dynamics::crate_world_model::{HierarchicalCfCWorldModel, WorldModelConfig};

const DIM: usize = 16;
const HIDDEN: usize = 24;
const TRAIN_SAMPLES: usize = 128;
const EVAL_SAMPLES: usize = 64;
const EPOCHS: usize = 12;
const DATA_SEED: u64 = 0xC0A8_2026_1029;
const MODEL_SEEDS: [u64; 5] = [
    0x5EED_0001,
    0x5EED_0002,
    0x5EED_0003,
    0x5EED_0004,
    0x5EED_0005,
];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct SplitMix64(u64);

impl SplitMix64 {
    fn new(seed: u64) -> Self {
        Self(seed)
    }

    fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    fn unit(&mut self) -> f32 {
        ((self.next_u64() >> 40) as f32) / ((1_u32 << 24) as f32)
    }

    fn signed(&mut self) -> f32 {
        self.unit() * 2.0 - 1.0
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Law {
    Source,
    ActionEffectReversal,
}

impl Law {
    fn name(self) -> &'static str {
        match self {
            Self::Source => "source_holdout",
            Self::ActionEffectReversal => "action_effect_reversal",
        }
    }

    fn action_coefficient(self) -> f32 {
        match self {
            Self::Source => 0.25,
            Self::ActionEffectReversal => -0.25,
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
struct Experience {
    state: Vec<f32>,
    action: Vec<f32>,
    next_state: Vec<f32>,
}

fn transition(state: &[f32], action: &[f32], law: Law) -> Vec<f32> {
    (0..DIM)
        .map(|i| {
            let neighbour = state[(i + 1) % DIM];
            0.55 * state[i] + law.action_coefficient() * action[i]
                + 0.06 * neighbour * action[i]
        })
        .collect()
}

fn dataset(seed: u64, count: usize, law: Law) -> Vec<Experience> {
    let mut rng = SplitMix64::new(seed);
    (0..count)
        .map(|_| {
            let state = (0..DIM).map(|_| rng.signed()).collect::<Vec<_>>();
            let action = (0..DIM).map(|_| rng.signed()).collect::<Vec<_>>();
            let next_state = transition(&state, &action, law);
            Experience {
                state,
                action,
                next_state,
            }
        })
        .collect()
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct Metrics {
    mse: f64,
    mae: f64,
    persistence_mse: f64,
    zero_mse: f64,
    persistence_mae: f64,
    sample_count: usize,
}

impl Metrics {
    fn evaluate(
        model: &HierarchicalCfCWorldModel,
        data: &[Experience],
    ) -> Result<Self, String> {
        let mut squared_error = 0.0_f64;
        let mut absolute_error = 0.0_f64;
        let mut persistence_squared_error = 0.0_f64;
        let mut persistence_absolute_error = 0.0_f64;
        let mut zero_squared_error = 0.0_f64;
        let mut count = 0_usize;

        for row in data {
            let prediction = model
                .predict(&row.state, &row.action, 1.0)
                .map_err(|error| format!("world-model prediction failed: {error}"))?;
            if prediction.len() != row.next_state.len() {
                return Err(format!(
                    "prediction dimension mismatch: got {}, expected {}",
                    prediction.len(),
                    row.next_state.len()
                ));
            }
            for i in 0..DIM {
                let error = prediction[i] as f64 - row.next_state[i] as f64;
                let persistence_error =
                    row.state[i] as f64 - row.next_state[i] as f64;
                let zero_error = row.next_state[i] as f64;
                squared_error += error * error;
                absolute_error += error.abs();
                persistence_squared_error += persistence_error * persistence_error;
                persistence_absolute_error += persistence_error.abs();
                zero_squared_error += zero_error * zero_error;
                count += 1;
            }
        }

        if count == 0 {
            return Err("evaluation dataset must not be empty".to_owned());
        }
        let denominator = count as f64;
        Ok(Self {
            mse: squared_error / denominator,
            mae: absolute_error / denominator,
            persistence_mse: persistence_squared_error / denominator,
            zero_mse: zero_squared_error / denominator,
            persistence_mae: persistence_absolute_error / denominator,
            sample_count: data.len(),
        })
    }
}

#[derive(Clone, Debug, PartialEq)]
struct SeedResult {
    seed: u64,
    final_epoch_train_mse: f64,
    source: Metrics,
    reversal: Metrics,
    training_steps: u64,
}

fn run_seed(seed: u64) -> Result<SeedResult, String> {
    let training = dataset(DATA_SEED, TRAIN_SAMPLES, Law::Source);
    let source_eval = dataset(DATA_SEED ^ 0x1111_2222_3333_4444, EVAL_SAMPLES, Law::Source);
    let reversal_eval = dataset(DATA_SEED ^ 0xAAAA_BBBB_CCCC_DDDD, EVAL_SAMPLES, Law::ActionEffectReversal);

    let config = WorldModelConfig {
        hdc_dim: DIM,
        hidden_dim: HIDDEN,
        learning_rate: 0.001,
        momentum: 0.9,
        consciousness_decay: 0.99,
    };
    let mut model = HierarchicalCfCWorldModel::new_with_seed(config, seed)
        .map_err(|error| format!("seeded model construction failed: {error}"))?;

    let mut final_epoch_loss = 0.0_f64;
    for _ in 0..EPOCHS {
        final_epoch_loss = 0.0;
        for row in &training {
            let loss = model
                .train_step(&row.state, &row.action, &row.next_state, 1.0)
                .map_err(|error| format!("world-model training failed: {error}"))?;
            final_epoch_loss += loss as f64;
        }
        final_epoch_loss /= TRAIN_SAMPLES as f64;
    }

    let source = Metrics::evaluate(&model, &source_eval)?;
    let reversal = Metrics::evaluate(&model, &reversal_eval)?;
    Ok(SeedResult {
        seed,
        final_epoch_train_mse: final_epoch_loss,
        source,
        reversal,
        training_steps: model.training_steps,
    })
}

fn mean(values: &[f64]) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    values.iter().sum::<f64>() / values.len() as f64
}

#[derive(Clone, Debug, PartialEq)]
struct Aggregate {
    mse: f64,
    mae: f64,
    persistence_mse: f64,
    zero_mse: f64,
    persistence_mae: f64,
    model_to_persistence_mse_ratio: f64,
}

fn aggregate(results: &[SeedResult], law: Law) -> Aggregate {
    let metrics = results.iter().map(|row| match law {
        Law::Source => row.source,
        Law::ActionEffectReversal => row.reversal,
    }).collect::<Vec<_>>();
    let mse = mean(&metrics.iter().map(|row| row.mse).collect::<Vec<_>>());
    let persistence_mse = mean(&metrics.iter().map(|row| row.persistence_mse).collect::<Vec<_>>());
    Aggregate {
        mse,
        mae: mean(&metrics.iter().map(|row| row.mae).collect::<Vec<_>>()),
        persistence_mse,
        zero_mse: mean(&metrics.iter().map(|row| row.zero_mse).collect::<Vec<_>>()),
        persistence_mae: mean(&metrics.iter().map(|row| row.persistence_mae).collect::<Vec<_>>()),
        model_to_persistence_mse_ratio: mse / persistence_mse.max(f64::MIN_POSITIVE),
    }
}

fn render(results: &[SeedResult]) -> String {
    let source = aggregate(results, Law::Source);
    let reversal = aggregate(results, Law::ActionEffectReversal);
    let mut out = format!(
        concat!(
            "{{\n",
            "  \"schema_version\": \"cmaq-008-world-model-adapter-v0.1\",\n",
            "  \"model\": \"HierarchicalCfCWorldModel\",\n",
            "  \"dimensions\": {{\"hdc\": {}, \"hidden\": {}}},\n",
            "  \"training\": {{\"samples\": {}, \"epochs\": {}, \"seeds\": {}}},\n",
            "  \"evaluation_samples_per_regime_per_seed\": {},\n",
            "  \"train_law\": {{\"state_coefficient\": 0.55, \"action_coefficient\": 0.25, \"interaction_coefficient\": 0.06}},\n",
            "  \"heldout_shift\": \"action_effect_reversal\",\n",
            "  \"regimes\": {{\n",
            "    \"source_holdout\": {{\"mse\": {:.8}, \"mae\": {:.8}, \"persistence_mse\": {:.8}, \"persistence_mae\": {:.8}, \"zero_mse\": {:.8}, \"model_to_persistence_mse_ratio\": {:.8}}},\n",
            "    \"action_effect_reversal\": {{\"mse\": {:.8}, \"mae\": {:.8}, \"persistence_mse\": {:.8}, \"persistence_mae\": {:.8}, \"zero_mse\": {:.8}, \"model_to_persistence_mse_ratio\": {:.8}}}\n",
            "  }},\n",
            "  \"per_seed\": [\n"
        ),
        DIM, HIDDEN, TRAIN_SAMPLES, EPOCHS, results.len(), EVAL_SAMPLES,
        source.mse, source.mae, source.persistence_mse, source.persistence_mae, source.zero_mse, source.model_to_persistence_mse_ratio,
        reversal.mse, reversal.mae, reversal.persistence_mse, reversal.persistence_mae, reversal.zero_mse, reversal.model_to_persistence_mse_ratio
    );

    for (index, row) in results.iter().enumerate() {
        out.push_str(&format!(
            concat!(
                "    {{\"seed\":\"{:016x}\",",
                "\"final_epoch_train_mse\":{:.8},",
                "\"training_steps\":{},",
                "\"source_mse\":{:.8},",
                "\"source_persistence_mse\":{:.8},",
                "\"reversal_mse\":{:.8},",
                "\"reversal_persistence_mse\":{:.8}",
                "}}"
            ),
            row.seed,
            row.final_epoch_train_mse,
            row.training_steps,
            row.source.mse,
            row.source.persistence_mse,
            row.reversal.mse,
            row.reversal.persistence_mse
        ));
        if index + 1 != results.len() {
            out.push(',');
        }
        out.push('\n');
    }
    out.push_str("  ]\n}\n");
    out
}

fn run() -> Result<Vec<SeedResult>, String> {
    let results = MODEL_SEEDS
        .iter()
        .map(|seed| run_seed(*seed))
        .collect::<Result<Vec<_>, _>>()?;
    if results.iter().any(|row| {
        !row.final_epoch_train_mse.is_finite()
            || !row.source.mse.is_finite()
            || !row.reversal.mse.is_finite()
            || row.training_steps != (TRAIN_SAMPLES * EPOCHS) as u64
    }) {
        return Err("non-finite metric or unexpected training-step count".to_owned());
    }
    Ok(results)
}

fn main() {
    let args = std::env::args().skip(1).collect::<Vec<_>>();
    if args.iter().any(|arg| arg == "--help" || arg == "-h") {
        println!(
            "CMAQ-008 real CfC world-model diagnostic: {} seeds, {} train samples x {} epochs, {} test samples per regime.",
            MODEL_SEEDS.len(), TRAIN_SAMPLES, EPOCHS, EVAL_SAMPLES
        );
        return;
    }
    if !args.is_empty() {
        eprintln!("unexpected argument {}; use --help", args[0]);
        process::exit(2);
    }
    match run() {
        Ok(results) => print!("{}", render(&results)),
        Err(error) => {
            eprintln!("{error}");
            process::exit(1);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn deterministic_data_generation_and_transition_laws() {
        assert_eq!(
            dataset(DATA_SEED, 8, Law::Source),
            dataset(DATA_SEED, 8, Law::Source)
        );
        assert_ne!(
            dataset(DATA_SEED, 8, Law::Source),
            dataset(DATA_SEED, 8, Law::ActionEffectReversal)
        );
        for law in [Law::Source, Law::ActionEffectReversal] {
            for row in dataset(DATA_SEED, 8, law) {
                assert_eq!(row.state.len(), DIM);
                assert_eq!(row.action.len(), DIM);
                assert_eq!(row.next_state.len(), DIM);
                assert!(row.next_state.iter().all(|value| value.is_finite()));
            }
        }
    }

    #[test]
    fn same_model_seed_replays_training_and_predictions() {
        let first = run_seed(MODEL_SEEDS[0]).unwrap();
        let second = run_seed(MODEL_SEEDS[0]).unwrap();
        assert_eq!(first, second);
    }

    #[test]
    fn report_uses_real_model_and_has_finite_source_and_shift_metrics() {
        let results = run().unwrap();
        assert_eq!(results.len(), MODEL_SEEDS.len());
        for row in &results {
            for value in [
                row.final_epoch_train_mse,
                row.source.mse,
                row.source.mae,
                row.source.persistence_mse,
                row.source.zero_mse,
                row.reversal.mse,
                row.reversal.persistence_mse,
                row.reversal.zero_mse,
            ] {
                assert!(value.is_finite() && value >= 0.0);
            }
            assert_eq!(row.training_steps, (TRAIN_SAMPLES * EPOCHS) as u64);
        }
        let text = render(&results);
        let parsed: serde_json::Value = serde_json::from_str(&text).unwrap();
        assert_eq!(parsed["schema_version"], "cmaq-008-world-model-adapter-v0.1");
        assert_eq!(parsed["model"], "HierarchicalCfCWorldModel");
        assert_eq!(parsed["per_seed"].as_array().unwrap().len(), MODEL_SEEDS.len());
    }
}
